#!/usr/bin/env python3
"""Build the public SKYBORG company site. Standard library only; dist is generated."""
from pathlib import Path
from html import escape as e
from urllib.parse import urlencode, quote
import json,os,shutil
R=Path(__file__).resolve().parent
C=json.loads((R/'site-config.json').read_text())
D=R/'dist'
URL=os.environ.get('SITE_URL',C['site_url']).rstrip('/')
EMAIL=C['support_email']; COMPANY=C['legal_name']
assert EMAIL=='admin@skyborglabs.com' and COMPANY=='SKYBORG ENTERPRISE LLC'
# Only replace the generator-owned output. Source assets live beside this script.
if D.exists():shutil.rmtree(D)
D.mkdir();(D/'assets').mkdir()
for asset in R.iterdir():
 if asset.suffix in ('.png','.webp','.jpg','.mp4','.vtt') or asset.name=='concept-preview-transcript.txt':shutil.copy2(asset,D/'assets'/asset.name)
for n in ['styles.css','script.js']:shutil.copy2(R/n,D/n)
PAGES=[]
def u(path,d=0):return '../'*d+path
def a(path,text,d=0,cls=''):return f'<a class="{cls}" href="{u(path,d)}">{text}</a>'
def eyebrow(t):return f'<div class="eyebrow">{t}</div>'
def mail(subject,body=''):return 'mailto:'+EMAIL+'?'+urlencode({'subject':subject,'body':body},quote_via=quote)
SUB=mail('Subscribe to SKYBORG email updates','Please subscribe this email address to SKYBORG game-development news, announcements, and promotional offers, including advertisements in newsletters. I understand I can unsubscribe at any time by replying Unsubscribe or emailing admin@skyborglabs.com. I have read the website Privacy Policy.')
UNSUB=mail('Unsubscribe from SKYBORG updates','Please stop sending marketing email to this email address.')
def newsletter(d):
 return f'''<section class="newsletter" id="email-updates"><div class="wrap newsletter-inner"><div>{eyebrow('Studio updates')}<h2>Follow the game’s development.</h2><p>Request email updates about SKYBORG games, development news, and promotional offers. Newsletters may include advertisements.</p></div><div class="newsletter-action"><a class="btn accent" href="{e(SUB)}">Subscribe by email <span aria-hidden="true">↗</span></a><p>Opens your email app. Send the request from the address you want subscribed. This button does not subscribe you automatically. Unsubscribe any time by email. {a('privacy/','Privacy Policy',d)}.</p></div></div></section>'''
def page(path,title,body,active='',description='',noindex=False):
 d=path.count('/');canonical=URL+'/'+path.removesuffix('index.html');desc=description or 'SKYBORG ENTERPRISE LLC develops original games and software. Explore Slingshot Wrestling, an Android-first game in pre-production.'
 nav=''.join(f'<a href="{u(p,d)}"'+(' aria-current="page"' if k==active else '')+f'>{label}</a>' for p,label,k in [('games/','Games','games'),('studio/','Company','studio'),('support/','Contact','support')])
 schema={'@context':'https://schema.org','@type':'Organization','name':COMPANY,'url':C['site_url'],'email':EMAIL,'logo':C['site_url']+'/assets/skyborg-logo.png','description':'Software and game development company.'}
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | {COMPANY}</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#191c1b"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{e(title)} | SKYBORG"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{URL}/assets/slingshot-ring.webp"><link rel="icon" type="image/svg+xml" href="{u('assets/favicon.svg',d)}"><link rel="stylesheet" href="{u('styles.css',d)}"><script defer src="{u('script.js',d)}"></script><script type="application/ld+json">{json.dumps(schema)}</script>{'<meta name="robots" content="noindex">' if noindex else ''}</head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="{u('index.html',d)}" aria-label="SKYBORG ENTERPRISE LLC home"><span class="logo"><img src="{u('assets/skyborg-logo.png',d)}" width="400" height="400" alt="SKYBORG"></span><span class="brand-text">ENTERPRISE LLC<br>GAME DEVELOPMENT</span></a><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false">Menu +</button><nav class="nav" id="main-nav" aria-label="Main navigation">{nav}<a class="contact-link" href="mailto:{EMAIL}">Get in touch <span aria-hidden="true">↗</span></a></nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap"><div class="footer-main"><div><div class="footer-name">{COMPANY}</div><p>Software & game development<br><a href="mailto:{EMAIL}">{EMAIL}</a></p></div><nav class="footer-nav" aria-label="Footer navigation">{a('games/','Games',d)}{a('studio/','Company',d)}{a('support/','Contact & support',d)}{a('privacy/','Privacy Policy',d)}</nav></div><div class="footer-bottom"><span>© 2026 {COMPANY}. All rights reserved.</span><span>Slingshot Wrestling is a working title.</span></div></div></footer></body></html>'''
 if noindex:
  import re
  html=re.sub(r'(href|src)="(?![a-z]+:|/|#)([^"]+)"',r'\1="/\2"',html)
 f=D/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(html)
 if not noindex:PAGES.append(canonical)
def head(label,title,description,d=1):return f'<section class="page-head wrap"><div class="crumb">{a("index.html","Home",d)} / {label}</div>{eyebrow(label)}<h1>{title}</h1><p>{description}</p></section>'
def feature(d):
 return f'''<div class="project-feature"><div><a class="feature-image" href="{u('games/slingshot-wrestling/',d)}"><img src="{u('assets/slingshot-ring-small.webp',d)}" width="800" height="534" alt="Concept art of two collectible wrestling figures facing off in a ring" loading="lazy"><span class="image-tag">In development · Android first</span></a><p class="image-caption">Concept visualization · Not a gameplay screenshot</p></div><div class="project-copy"><div class="tagline">Collectible slingshot wrestling RPG</div><h3>Slingshot Wrestling</h3><p>Build a stable of original wrestling figures. Plan your launch, use the ropes, and work toward a three-count pin. Between matches, develop your wrestlers and manage their careers.</p><dl class="specs"><div><dt>Development stage</dt><dd>Pre-production</dd></div><div><dt>Planned first platform</dt><dd>Android / Google Play</dd></div><div><dt>Release date</dt><dd>Not announced</dd></div></dl>{a('games/slingshot-wrestling/','Explore the game <span aria-hidden="true">↗</span>',d,'btn')}</div></div>'''
page('index.html','Original Games & Software',f'''<section class="hero"><img class="hero-image" src="assets/slingshot-ring.webp" width="1536" height="1024" alt="Concept visualization of collectible wrestlers in a neighborhood gym ring" fetchpriority="high"><div class="wrap hero-content">{eyebrow(COMPANY)}<h1>Original games.<br><em>Android first.</em></h1><p>We develop games and software. Our current project, Slingshot Wrestling, combines collectible wrestlers, tactical slingshot matches, and stable management.</p><div class="actions">{a('games/slingshot-wrestling/','Discover Slingshot Wrestling ↗',0,'btn accent')}{a('studio/','About the company ↗',0,'text-link')}</div></div><div class="hero-note">Slingshot Wrestling · Pre-production concept art · Not captured gameplay</div></section><div class="status-bar"><div class="wrap status-inner"><strong>SKYBORG ENTERPRISE LLC</strong><span>Software & game development</span><span>Android / Google Play · Planned platform</span></div></div><section class="section wrap"><div class="section-heading"><div>{eyebrow('Current project')}<h2>Step into the ring.</h2></div></div>{feature(0)}</section><section class="company-section section"><div class="wrap company-grid"><div>{eyebrow('The company')}<h2>Original characters.<br>A game built around them.</h2></div><div><p>SKYBORG ENTERPRISE LLC is a software and game development company. Our current development work focuses on an Android-first collectible wrestling game, with original characters and a Retro Arcade Anime visual direction.</p><p>The project is in pre-production. No playable demo or commercial release is available yet.</p>{a('support/','Contact SKYBORG ↗',0,'text-link')}</div></div></section>{newsletter(0)}''')
page('games/index.html','Games',head('Games','Slingshot Wrestling','Our current game project: collectible wrestling figures, tactical launches, and a stable-management career.')+f'<section class="wrap page-body">{feature(1)}</section>'+newsletter(1),'games')
project=f'''<section class="hero project-hero"><img class="hero-image" src="../../assets/slingshot-ring.webp" width="1536" height="1024" alt="Concept art of a slingshot wrestling match with two miniature figures" fetchpriority="high"><div class="wrap hero-content"><div class="project-title">Slingshot Wrestling</div><h1>Pull back.<br>Hit the ropes.<br><em>Win the count.</em></h1><p>A collectible wrestling RPG built around aim-and-release matches and the career of your own stable of original wrestlers.</p><div class="actions"><a class="btn accent" href="#concept-video">Watch the concept preview ▷</a><a class="text-link" href="#how-it-works">How matches work ↓</a></div><div class="project-info"><span>Working title</span><span>Pre-production</span><span>Android first</span></div></div><div class="hero-note">Concept visualization · Not captured gameplay</div></section><section class="section wrap" id="how-it-works"><div class="intro-grid"><div>{eyebrow('The match concept')}<h2>Read the ring.<br>Make your move.</h2></div><div><p>The planned singles format places one collectible figure on each side. Aim a launch, use controlled rope rebounds, and create an opening for a pin.</p><p>Stamina supports actions; Resilience reflects match wear and resistance to pins. Launches, impacts, and pin timing are design targets being developed and tested.</p></div></div><div class="steps"><article class="step"><span class="number">01 / AIM</span><h3>Pull back & release.</h3><p>Drag to choose a direction. A limited aiming cue helps you plan the opening move.</p></article><article class="step"><span class="number">02 / REBOUND</span><h3>Use the ropes.</h3><p>Positioning and controlled rebounds shape each launch. Wait for movement to settle before the next phase.</p></article><article class="step"><span class="number">03 / PIN</span><h3>Go for the three-count.</h3><p>Create a knockdown and an eligible cover opportunity. Pins depend on the match state, not just a collision.</p></article></div></section><section class="section media-section" id="concept-video"><div class="wrap"><div class="section-heading"><div>{eyebrow('Motion study')}<h2>A match, in principle.</h2></div><span class="small-note">15-second animated design illustration · Silent</span></div><div class="video-frame"><video controls playsinline preload="none" poster="../../assets/match-preview-poster.jpg" aria-label="Animated concept preview of aim, rope rebound, and a three-count pin"><source src="../../assets/slingshot-concept-preview.mp4" type="video/mp4"><track kind="captions" src="../../assets/concept-preview.vtt" srclang="en" label="English" default>Your browser does not support embedded video. <a href="../../assets/slingshot-concept-preview.mp4">Download the concept preview.</a></video></div><div class="media-caption"><span>Illustrates the proposed match sequence. Not footage of an implemented game. No audio.</span><a href="../../assets/concept-preview-transcript.txt">Read the text description ↗</a></div></div></section><section class="section wrap"><div class="section-heading"><div>{eyebrow('Visual development')}<h2>Figures with a fighting style.</h2></div></div><div class="gallery-grid"><button class="gallery-card" data-full="../../assets/slingshot-ring.webp" data-title="The local ring" aria-haspopup="dialog"><img src="../../assets/slingshot-ring-small.webp" width="800" height="534" loading="lazy" alt="Two miniature wrestling figures in a worn neighborhood gym ring"><h3>The local ring ↗</h3><p>A modest gym, readable ring space, and figures on puck-like bases.</p></button><button class="gallery-card" data-full="../../assets/wrestler-collection.webp" data-title="Original wrestler directions" aria-haspopup="dialog"><img src="../../assets/wrestler-collection-small.webp" width="800" height="534" loading="lazy" alt="Concept lineup of a masked flyer, star-themed showman, and heavyweight wrestler"><h3>Original wrestler directions ↗</h3><p>Contrasting silhouettes in a Retro Arcade Anime style.</p></button></div><p class="image-caption">AI-generated concept visualizations based on the game design document. Characters, interfaces, and final game art may change.</p></section><section class="section company-section"><div class="wrap intro-grid"><div>{eyebrow('Beyond the match')}<h2>Build a stable.<br>Develop a career.</h2></div><div><p>The career design follows a stable from a rundown local gym toward larger wrestling circuits. Planned systems include collecting and training figures, selecting bookings, managing travel and recovery, and developing allies and rivals.</p><p>Rubber and painted figure finishes, career outfits, and entrance music are part of the visual and collection direction. Final content, release scope, and dates have not been announced.</p><dl class="specs"><div><dt>Developer</dt><dd>{COMPANY}</dd></div><div><dt>Stage</dt><dd>Pre-production</dd></div><div><dt>Planned platform</dt><dd>Android / Google Play</dd></div><div><dt>Demo / release</dt><dd>Not available</dd></div></dl></div></div></section>{newsletter(2)}<dialog class="dialog" id="art-viewer" aria-labelledby="art-title"><button class="dialog-close" aria-label="Close concept image">×</button><img alt="Concept artwork"><div class="dialog-info"><h2 id="art-title"></h2><p>AI-generated concept visualization · Not captured gameplay</p></div></dialog>'''
page('games/slingshot-wrestling/index.html','Slingshot Wrestling',project,'games','Explore the concept for Slingshot Wrestling: original collectible figures, tactical rope rebounds, three-count pins, and stable management. In pre-production for Android.')
page('studio/index.html','Company',head('Company',COMPANY,'Software and game development.')+f'''<section class="wrap page-body"><div class="two-col"><article class="prose"><p class="lead">We develop original games and software, with an initial focus on Android.</p><p>Our current project is Slingshot Wrestling, a working-title collectible wrestling RPG. Its design combines short tactical slingshot matches, character collection and training, and a stable-management career.</p><h2>Current development</h2><p>The project is in pre-production. Current work includes game design, character direction, match systems, and planning the first playable prototype.</p><p>The concept images and motion study on this site communicate the intended experience. They do not represent a released game or a completed build.</p><h2>Business contact</h2><p>For business inquiries, press, or questions about the project, contact <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></article><aside><img class="company-picture" src="../assets/wrestler-collection.webp" width="1536" height="1024" alt="Original collectible wrestler concept lineup"><p class="image-caption">Slingshot Wrestling · Character concept directions</p><dl class="specs"><div><dt>Legal company name</dt><dd>{COMPANY}</dd></div><div><dt>Website</dt><dd>www.skyborglabs.com</dd></div><div><dt>Focus</dt><dd>Software & games</dd></div></dl></aside></div></section>''','studio')
page('support/index.html','Contact & Support',head('Contact & support','Contact SKYBORG.','Business inquiries, project questions, email preferences, and privacy requests.')+f'''<section class="wrap page-body"><div class="two-col"><div><details open><summary>Where can I play Slingshot Wrestling?</summary><p>The game is in pre-production. No playable demo or commercial release is available. Official release information will be added to the game page.</p></details><details><summary>How do I request development updates?</summary><p>Use Subscribe by email below and send the prefilled request. Updates may include game-development news, promotional offers, and advertisements. A support inquiry does not automatically subscribe you.</p></details><details><summary>How do I unsubscribe or request deletion?</summary><p>Email {EMAIL} from the affected address with the subject “Unsubscribe” or “Privacy request.” You can also reply “Unsubscribe” to a newsletter. We may need information to verify a privacy request.</p></details><details><summary>Are the images and video actual gameplay?</summary><p>No. They are concept visualizations and an animated explanation of the planned match sequence. Actual gameplay footage will be identified as such when available.</p></details></div><aside class="contact-panel"><h2>SKYBORG ENTERPRISE LLC</h2><dl class="contact-details"><dt>Email</dt><dd><a href="mailto:{EMAIL}">{EMAIL}</a></dd><dt>Website</dt><dd><a href="https://www.skyborglabs.com">www.skyborglabs.com</a></dd><dt>Privacy & email preferences</dt><dd><a href="{e(UNSUB)}">Request unsubscribe</a></dd></dl><p>Please do not send passwords or payment-card details in your message.</p></aside></div></section>'''+newsletter(1),'support')
privacy=f'''<section class="wrap page-body"><article class="prose"><p class="policy-date">Effective date: October 6, 2026</p><p>This Privacy Policy explains how {COMPANY} (“SKYBORG,” “we,” “us”) handles information relating to www.skyborglabs.com and email communications with the studio. Questions and requests can be sent to <a href="mailto:{EMAIL}">{EMAIL}</a>.</p><h2>Information we receive</h2><p>If you email us, we receive your email address, any name you provide, the content of your message, and attachments you choose to send. If you request newsletter updates, we use your email address and your subscription or unsubscribe request to manage those communications.</p><p>Our hosting and email service providers may process technical information needed to operate and protect their services, such as IP addresses, browser information, timestamps, request logs, and email delivery information. Their handling of service data is also governed by their own privacy policies.</p><h2>How we use information</h2><ul><li>Respond to support, business, press, and privacy inquiries.</li><li>Send requested game-development news, announcements, promotional offers, and newsletters, which may include advertisements.</li><li>Manage subscription preferences, prevent unwanted email, and maintain the security of our communications.</li><li>Meet applicable legal obligations and resolve disputes.</li></ul><h2>Email updates and marketing</h2><p>Subscription on this website works by email request. Selecting “Subscribe by email” opens your email application with a prefilled request; you must send it before we receive it. The site does not automatically enroll visitors or people who contact support.</p><p>You can stop marketing messages at any time by replying “Unsubscribe” or emailing <a href="{e(UNSUB)}">{EMAIL} with the subject “Unsubscribe”</a>. Unsubscribing does not prevent a response to an inquiry you send separately.</p><h2>Service providers and disclosures</h2><p>Information may be processed by providers used for website hosting, email delivery, and related operations, as needed to provide those services. We may also disclose information when required by applicable law or to protect rights and security. Including an advertisement in a newsletter does not itself authorize disclosure of your email address to the advertiser.</p><p>This website does not sell visitor information or send email addresses to advertising networks. Links in promotional messages may lead to third-party sites with their own privacy practices.</p><h2>Cookies, analytics, and embedded media</h2><p>The public website’s code does not set cookies or use analytics, advertising trackers, social-media widgets, or third-party video embeds. Concept media is served with the website. A hosting provider may process technical requests to deliver and protect the site. If you visit a separate sign-in-protected review preview, its provider’s authentication and privacy practices apply separately.</p><h2>Retention and your choices</h2><p>We retain correspondence as needed to respond to your request and maintain necessary business records. We keep subscription details while you are subscribed. After an unsubscribe request, we may retain the minimum information needed to honor your preference and avoid sending further marketing messages. Records may be kept longer where required by law.</p><p>You may ask to access, correct, or delete information you have provided, or withdraw permission for marketing emails, by contacting {EMAIL}. Depending on where you live, you may have additional privacy rights and the right to complain to a data protection authority. We may verify your request before acting on it.</p><h2>Security and service locations</h2><p>We use reasonable safeguards appropriate to the information we handle. No internet transmission or storage method is completely secure. Hosting and email providers may process information in countries other than your own, subject to applicable requirements.</p><h2>Children’s information</h2><p>The website’s email update service is intended for adults. We do not knowingly seek newsletter subscriptions from children under 13. If you believe a child has provided personal information, contact us so we can review and remove it as appropriate. This is not an age rating for the planned game.</p><h2>Games in development</h2><p>Slingshot Wrestling is in pre-production. This website does not provide a game download, game account, in-app purchases, rewarded ads, or game telemetry. This policy does not claim to describe the data practices of a future released app. App-specific privacy information will be provided before the relevant game services collect information.</p><h2>Changes and contact</h2><p>We will update this page when our practices change and revise the effective date. Material changes will be communicated as appropriate.</p><p>{COMPANY}<br><a href="mailto:{EMAIL}">{EMAIL}</a><br>www.skyborglabs.com</p></article></section>'''
page('privacy/index.html','Privacy Policy',head('Privacy','Privacy Policy','Website, correspondence, and email updates.')+privacy,description='Privacy Policy for SKYBORG ENTERPRISE LLC: website information, email updates, promotional messages, unsubscribe choices, and privacy requests.')
page('404.html','Page Not Found',f'<section class="wrap not-found">{eyebrow("404")}<h1>Page not found.</h1><p>The address may have changed.</p>{a("index.html","Return to SKYBORG ↗",0,"btn")}</section>',noindex=True)
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+x+'</loc></url>' for x in PAGES)+'</urlset>')
(D/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+URL+'/sitemap.xml\n')
(D/'.nojekyll').touch()
(D/'CNAME').write_text(C['custom_domain']+'\n')
(D/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="10" fill="#191c1b"/><text x="32" y="47" text-anchor="middle" font-family="Arial" font-size="44" font-weight="900" fill="#ed6737">S</text></svg>')
print('Built',len(PAGES),'public pages plus 404; custom domain:',C['custom_domain'])
